
local tys=[==[]==]
local tcf=
(function(...)
local lr={55,123,67,190,64,224,41,156,143,54,120,205,240,171,200,121,198,154,77,99,162,192,175,250,44,205,64,231}
local rx=bit32 or bit
local gl=rx.bxor
for cy=1,#lr do lr[cy]=gl(lr[cy],(76*cy+242)%256) end
local oae="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local ke={}
for jy=1,#oae do ke[oae:byte(jy)]=jy-1 end
local function dic(str)
  local R={} local acc,nb=0,0
  for ir=1,#str do
    local v=ke[str:byte(ir)]
    if v then
      acc=acc*64+v; nb=nb+6
      if nb>=8 then nb=nb-8; R[#R+1]=math.floor(acc/2^nb)%256; acc=acc%2^nb end
    end
  end
  return R
end
local function bw(key,data)
  local S={} for qh=0,255 do S[qh]=qh end
  local j=0
  for dkzlp=0,255 do
    j=(j+S[dkzlp]+key[(dkzlp%#key)+1])%256
    S[dkzlp],S[j]=S[j],S[dkzlp]
  end
  local O={} local ii=0; j=0
  for n=1,#data do
    ii=(ii+1)%256; j=(j+S[ii])%256; S[ii],S[j]=S[j],S[ii]
    O[n]=string.char(gl(data[n],S[(S[ii]+S[j])%256]))
  end
  return table.concat(O)
end
local code=bw(lr,dic(""))
local nf,ne=(loadstring or load)("return "..code)
if not nf then error(ne or "rage quit chain error") end
local tq=nf()
return function(big) return tq(big) end
end)(...)

return tcf(tys)
